def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    current = None
    for base in classes:
        if current is None:
            current = base
        else:
            if base in [b for b in current.mro()]:
                # Preserve order
                current = base
    return current

