    namesAndDescs = {}
    for name in self.getNames():
        desc = self.getDescription(name)
        namesAndDescs[name] = desc
    if all:
        for cls in inspect.getmro(self.__class__):
            for name in cls.__dict__.keys():
                if name.startswith("_"):
                    continue
                if name in namesAndDescs:
                    continue
                desc = cls.__dict__.get(name, None)
                if isinstance(desc, ABCMeta):
                    if desc.abstractmethods:
                        continue
                namesAndDescs[name] = desc
    return namesAndDescs

