def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a partial observer_schema from a Kubernetes resource's partial
    manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This method recursively processes each JSON object in the manifest_dict and
    creates a new dictionary from it, replacing all non-list and non-dict values by
    None. If the argument first_level is True, it also copies the values of the
    identifying fields from the manifest file.
    """

    def handle_single_value(value):
        if isinstance(value, list):
            return [generate_default_observer_schema_dict(element, first_level) for element in value]
        if isinstance(value, dict):
            return generate_default_observer_schema_dict(value, first_level)
        return None

    result = {}

    for key, value in manifest_dict.items():
        if key == 'id':
            continue
        result[key] = handle_single_value(value)

    if first_level:
        result['name'] = manifest_dict['metadata']['name']
        result['namespace'] = manifest_dict['metadata']['namespace']
        result['uid'] = manifest_dict['metadata']['uid']

    return result

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):

    assert isinstance(last_applied_manifest, list)
    assert isinstance(observer_schema, list)
    assert isinstance(response, list)

    for idx, resp_elem in enumerate(response):
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append(None)

        if resp_elem is not None:
            last_applied_manifest_elem = last_applied_manifest[idx]
            observer_schema_elem = observer_schema[idx]

