                update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response)
    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Recursively update a partial ``last_applied_manifest`` from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): Partial ``last_applied_manifest`` being updated.
        observer_schema (list): Partial ``observer_schema``.
        response (list): Partial response from the Kubernetes API.
    """
    for field in response:
        if field not in last_applied_manifest:
            last_applied_manifest.append(field)
        if field in observer_schema:
            if isinstance(observer_schema[field], list):
                if isinstance(response[field], list):
                    update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
                else:
                    last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
            else:
                last_applied_manifest[field] = response[field]
    return last_applied_manifest

def format(self, sql, params):
    if self.in_style == "named":
        if not isinstance(params, dict):
            raise ValueError("params must be a dict")
    elif self.in_style == "ordinal":
        if not isinstance(params, list):
            raise ValueError("params must be a list")
    else:
        raise ValueError("invalid in_style")

    out_params = {}

    if self.in_style == "named":
        for name, value in params.items():
            if isinstance(value, Snowflake):
                out_params[name] = value.to_out_style()
            else:
                out_params[name] = value
    elif self.in_style == "ordinal":
        index = 0
        for name, _, arg in get_args(sql):
            if isinstance(arg, Snowflake):
                out_params[index] = arg.to_out_style()
            else:
                out_params[index] = arg
            index += 1
    else:
        raise ValueError("invalid in_style")

    return (
        sql.replace("($", "{}, ".format(",".join(out_params.keys())), 1),
        out_params
    )

def format(self, sql, params):
    if not isinstance(params, (dict, list)):
        raise TypeError("params must be a dict or list")

    in_style = self.in_style
    if in_style is None:
        raise ValueError("in_style is not set")

    if isinstance(sql, bytes):
        sql = sql.decode("utf-8")

    if in_style == "named":
        if not isinstance(params, dict):
            raise ValueError("params must be a dict for named parameter style")
        # convert named parameters to positional parameters
        pos_params = []
        for param in re.findall(r":([a-zA-Z_][a-zA-Z0-9_]*|\?|\{[a-zA-Z_][a-zA-Z0-9_]*\})", sql):
            pos_params.append(params.pop(param))
        sql = sql % tuple(pos_params)
        return sql, params
    elif in_style == "positional":
        if not isinstance(params, list):
            raise ValueError("params must be a list for positional parameter style")
        sql = sql % tuple(params)
        return sql, {}
    else:
        raise ValueError("invalid in_style: " + str(in_style))

def format(self, sql, params):
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        Parameters:
            sql (:class:`str` or :class:`bytes`): The SQL query.
            params (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`):
                The set of in-style parameters.

        Returns:
            :class:`tuple`: The formatted SQL query and the set of
            converted out-style parameters.
        """
        if not isinstance(sql, (str, bytes)):
            raise TypeError("sql must be str or bytes, not " + type(sql).__name__)

        if not isinstance(params, (dict, list)):
            raise TypeError("params must be dict or list, not " + type(params).__name__)

        if isinstance(params, dict) and not self.in_style:
            raise ValueError("in_style must be a named parameter style if params is a dict")

        if isinstance(params, list) and self.in_style:
            raise ValueError("in_style must be an ordinal parameter style if params is a list")

        out_params = {}

        if isinstance(params, dict):
            out_params = {k: v[0] for k, v in params.items()}

        elif isinstance(params, list):
            out_params = {":param{}".format(i+1): v for i, v in enumerate(params)}

        formatted_sql = re.sub(r"(?<=[^\\]):([a-zA-Z_][a-zA-Z0-9_]*)", lambda m: ":{}".format(out_params[m.group(0)]), sql)

        return formatted_sql, out_params

