def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    errors = []

    # Check for required fields
    for k in ['manifest', 'algorithm', 'digest', 'mime-type']:
        if k not in fixity:
            errors.append(f'Missing required field "{k}" in fixity block')

    # Check that the manifest field references a valid manifest file
    manifest_file = fixity['manifest']
    if manifest_file not in manifest_files:
        errors.append(f'Invalid manifest file "{manifest_file}" in fixity block')

    # Check that the algorithm field is one of the supported algorithms
    algorithm = fixity['algorithm']
    if algorithm not in ['md5', 'sha1', 'sha256', 'sha512']:
        errors.append(f'Unsupported algorithm "{algorithm}" in fixity block')

    # Check that the digest field is a valid digest for the specified algorithm
    digest = fixity['digest']
    if not validate_digest(algorithm, digest):
        errors.append(f'Invalid digest "{digest}" for algorithm {algorithm} in fixity block')

    # Check that the mime-type field is a valid mime type for the file
    mime_type = fixity['mime-type']
    if not validate_mime_type(mime_type):
        errors.append(f'Invalid mime type "{mime_type}" in fixity block')

    if errors:
        return errors
    else:
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check that fixity is a list of mappings
    if not isinstance(fixity, list):
        raise ValueError("fixity must be a list of mappings")
    for f in fixity:
        # Check that each mapping has two key-value pairs
        if not isinstance(f, collections.Mapping) or len(f) != 2:
            raise ValueError("fixity mapping must have two key-value pairs")

        # Check keys
        keys = set(f.keys())
        if keys != {'file', 'checksum'}:
            raise ValueError("fixity mapping must have 'file' and 'checksum' keys")

        # Check value types
        file_value = f['file']
        if not isinstance(file_value, str):
            raise ValueError("file value in fixity mapping must be a string")
        checksum_value = f['checksum']
        if not isinstance(checksum_value, str):
            raise ValueError("checksum value in fixity mapping must be a string")

        # Check file value
        if not file_value in manifest_files:
            raise ValueError(f"file {file_value} in fixity mapping not found in manifest")

        # Check checksum value
        if any(char not in string.hexdigits for char in checksum_value):
            raise ValueError("checksum value in fixity mapping must be a hexadecimal string")
        if len(checksum_value) != 40:
            raise ValueError("checksum value in fixity mapping must be a SHA-1 hash")

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # check if fixity block is a list
        if not isinstance(fixity, list):
            raise ValueError("Fixity block is not a list")

        # check if all entries are dicts
        for entry in fixity:
            if not isinstance(entry, dict):
                raise ValueError("Fixity block entry is not a dict")

        # check if all required keys are present
        for entry in fixity:
            if not all(k in entry for k in ("file", "sha256", "sha1", "md5")):
                raise ValueError("Fixity block entry is missing required keys")

        # check if all file entries are valid
        for entry in fixity:
            file_name = entry["file"]
            if file_name not in manifest_files:
                raise ValueError(f"File {file_name} in fixity block not found in manifest")

        # check if all SHA hash entries are valid
        for entry in fixity:
            for hash_type in ("sha256", "sha1", "md5"):
                hash_value = entry[hash_type]
                if not isinstance(hash_value, str) or not hash_value.isalnum():
                    raise ValueError(f"Invalid {hash_type} hash {hash_value} in fixity block")

        return True

