    listed in the manifest are referenced.
    """
    if not fixity or not manifest_files:
        raise ValueError("Fixity block or manifest file not provided.")

    for file in manifest_files:
        if file["file_name"] not in fixity:
            raise ValueError(f"File {file['file_name']} is not found in the manifest.")

    for file in fixity:
        if file["file_name"] not in manifest_files:
            raise ValueError(f"File {file['file_name']} is not found in the manifest.")

    for file in manifest_files:
        if file["file_name"] in fixity:
