    packages = {}
    for file in os.listdir(folder):
        if os.path.isdir(os.path.join(folder, file)):
            continue
        basename = os.path.splitext(file)[0]
        if basename not in packages:
            packages[basename] = []
        packages[basename].append(os.path.join(folder, file))
    return packages

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """

    result = {}
    for file in os.listdir(folder):
        if file.endswith('.xml'):
            package, id = os.path.splitext(file)[0].split('-')
            if package not in result:
                result[package] = {
                    'id': id,
                    'files': []
                }
            result[package]['files'].append(os.path.join(folder, file))

    return result

