def _extract_number_and_supplment_from_issue_element(issue):
    match = re.match(r"(\d+) ?((suppl\.\s)?\d+)?", issue)
    if match:
        number = match.group(1)
        supplement = match.group(2)
        if supplement is not None:
            supplement = supplement.lstrip("suppl.")
            if supplement.endswith(".1"):
                supplement = supplement.rstrip(".1")
    return (number, supplement)

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the numbers and suppl from the issue element.

    Returns:
        tuple(int|None, str|None): The number and supplement, or (None, None) if there is no number or supplement.
    """
    # first, extract all the number and supplement components from the issue element
    number = None
    supplement = None
    components = issue.split()
    for component in components:
        if component.isdigit():
            if number is None:
                number = int(component)
            else:
                supplement = component
        elif component.startswith("S"):
            if supplement is None:
                supplement = component
            else:
                supplement = supplement + " " + component
    # then, if the issue element contains only numbers, return the number as the only value
    if not supplement:
        return (number,)
    # otherwise, return a tuple containing both the number and supplement
    return (number, supplement)

