    """Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for i, arg in enumerate(args):
        for arg2 in args[i+1:]:
            if arg.involves(arg2) or arg2.involves(arg):
                if (arg == arg2) and (arg.operator == "|"):
                    result.append(arg.copy().flip().operands[0])
                elif (arg == arg2) and (arg.operator == "&"):
                    result.append(arg.copy())
                elif (arg != arg2) and (arg.operator == "|"):
                    result.append(arg.copy().flip().operands[1])
                elif (arg != arg2) and (arg.operator == "&"):
                    result.append(arg.copy().flip())
    return result

