    # Start with the root node
    node = self
    num_objects = 0
    good_objects = 0

    while node is not None:
        # Check each object in the node
        for obj in node.objects:
            num_objects += 1
            if validate_objects:
                if not obj.validate():
                    if show_warnings:
                        print(f"Invalid object {obj.id} found in node {node.id}")
                else:
                    good_objects += 1

        # Check the node's parent
        if node.parent is not None:
            node = node.parent
        else:
            break

    return num_objects, good_objects

