def deep_merge_nodes(nodes):
    merged_nodes = []

    for i, node in enumerate(nodes):
        key = node[0]
        value = node[1]

        if i < len(nodes) - 1:
            merge_node = nodes[i + 1][1]
        else:
            merge_node = None

        if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(merge_node, ruamel.yaml.nodes.MappingNode):
            # deep merge child nodes
            merged_node = deep_merge_nodes([(key, value), (merge_node,)])
            merged_nodes.append(merged_node)
        elif isinstance(value, ruamel.yaml.nodes.MappingNode):
            # merge a key-value pair
            merged_nodes.append(node)

            if merge_node and key.value in merge_node.value:
                # ancestor node has this key, so merge values
                value.value[key.value] = deep_merge_nodes([(key, value.value[key.value]), (merge_node,)])
        else:
            # non-mapping node or last node
            merged_nodes.append(node)

    return merged_nodes

def deep_merge_nodes(nodes):
    result = []

    for node in nodes:
        key, value = node
        found = False
        for i in range(len(result)):
            result_key, result_value = result[i]
            if result_key == key:
                if isinstance(result_value, ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                    result_value.value.extend(value.value)
                else:
                    result[i] = (key, value)
                found = True
                break

        if not found:
            result.append((key, value))

    return result

