    bookmarks = []

    for value in values:
        parts = value.split(":")
        if len(parts) != 3:
            raise ValueError("Invalid bookmark value: " + value)

        try:
            page_number = int(parts[1])
        except ValueError:
            raise ValueError("Invalid page number in bookmark value: " + value)

        bookmarks.append(Bookmark(parts[0], page_number))

    return bookmarks

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """

    # Check if seq is of a sequence type
    if isinstance(seq, list):
        # If seq is of a sequence type, return as is
        return seq, type(seq)
    elif isinstance(seq, str):
        # If seq is a string, return a list of characters
        return list(seq), type(seq)
    elif bufsize:
        # If seq is a file-like object, return a list of size bufsize
        return list(seq.read(bufsize)), type(seq)
    else:
        # If seq is not a sequence type or a file-like object, raise an error
        raise ValueError(f"{seq} is not a sequence type or a file-like object")

def get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.

    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        raise ValueError("Expected sequence, got string: {}".format(seq))
    if isinstance(seq, bytes):
        if bufsize is None:
            bufsize = len(seq)
        return seq[:bufsize], bytes
    elif isinstance(seq, bytearray):
        if bufsize is None:
            bufsize = len(seq)
        return seq[:bufsize], bytearray
    else:
        # We're going to call list() on this sequence, which will consume
        # it. If it's an iterator, we want to make sure that it stays
        # an iterator, not a list.
        if hasattr(seq, '__iter__') and not hasattr(seq, '__getitem__'):
            seq = iter(seq)
        if bufsize is None:
            bufsize = len(seq)
        seq_list = list(seq[:bufsize])
        seq = iter(seq_list)
        return seq_list, type(seq_list)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """

    import collections

    if not isinstance(seq, collections.abc.Sequence):
        seq = [seq]

    if not bufsize:
        bufsize = len(seq)

    seq_type = type(seq[0])

    for i in range(len(seq)):
        if not isinstance(seq[i], seq_type):
            raise ValueError("All sequence elements must be of the same type")

    return seq[:bufsize], seq_type

