        if other is not None:
            if self.scale == 0:
                raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
            if isinstance(other, (numbers.Real, numbers.Integral)):
                self.fill = [int(round(other * x)) for x in self.fill]
                self.scale = other
            else:
                raise LenaTypeError("Invalid scale value. Expected a number.")
        if self.scale == 0 and not recompute:
            return self.scale
        else:
            return sum(self.fill)

def scale(self, other=None, recompute=False):
    if other is None:
        return self.scale

    if not self.scale or recompute:
        raise ValueError("Invalid scale to rescale")

    if other <= 0:
        raise LenaValueError("Negative or null scale")

    scale = self.scale
    total_count = self.total_count
    scale_factor = other / scale

    for value, count in self.items():
        new_count = int(round(count * scale_factor))
        self[value] = new_count

    self.scale = other
    self.total_count = int(round(total_count * scale_factor))

    return None

