def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc
    elif len(bases) == 1:
        return type(bases[0])
    else:
        s, b = 0, 1
        while s < len(bases)-1:
            if issubclass(bases[s],type(bases[b])):
                s += 1
            else:
                b += 1
                if s != b:
                    bases[s], bases[b] = bases[b], bases[s]
        return type(bases[0])

