def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """

    in_regex = r"^in-(@"
    for parameter in self._parameters:
        in_regex += parameter.name + "|"
    in_regex += r"@)\s*"
    return re.compile(in_regex)

def _create_in_regex(self):
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    from re import Pattern, compile

    # Create the regular expression
    regex = r"in\("
    for param in self.params:
        # Handle the parameter name
        if param.name:
            regex += param.name
        else:
            regex += param.type.name

        # Handle the parameter type
        if param.type.is_class:
            regex += r"<" + ",".join([p.name for p in param.type.generics]) + ">"
        else:
            regex += param.type.name

        # Handle the parameter default value
        if param.value:
            regex += r"=" + str(param.value)

        # Handle the comma
        if param != self.params[-1]:
            regex += r","

    # Close the pattern
    regex += r"\)"

    # Return the compiled regular expression
    return compile(regex)

