def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("Expected a string value for 'timestr', got '{}'.".format(type(timestr).__name__))

    if not isinstance(default, (datetime.datetime, type(None))):
        raise TypeError("Expected a 'datetime.datetime' object or 'None' for 'default', got '{}'.".format(default.__class__.__name__))

    if not isinstance(ignoretz, bool):
        raise TypeError("Expected a boolean value for 'ignoretz', got '{}'.".format(type(ignoretz).__name__))

    if tzinfos is not None:
        if not isinstance(tzinfos, dict) and not callable(tzinfos):
            raise TypeError("Expected a dictionary or a callable object for 'tzinfos', got '{}'.".format(tzinfos.__class__.__name__))

    # Set default parameters
    if default is None:
        default = datetime.datetime.now()

    try:
        # Parse the date/time string
        result = strptime(timestr, default, ignoretz, tzinfos, **kwargs)
    except ParserError as e:
        # Raise a custom exception with a more informative message
        raise datetime.datetimeparseerror(e, timestr)
    except OverflowError as e:
        # Raise a custom exception with a more informative message
        raise datetime.dateonexception(e, timestr)

    if not isinstance(result, datetime.datetime):
        raise TypeError("Expected a 'datetime.datetime' object, got '{}'.".format(result.__class__.__name__))

    return result

