def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message.
    The check if this is a legacy payload.
    """
    public_count = 0
    private_count = 0
    legacy_count = 0

    for msg in request.messages:
        if msg.private:
            private_count += 1
        else:
            public_count += 1

        if msg.legacy_payload:
            legacy_count += 1

    if private_count > public_count:
        return "private"
    elif public_count > private_count:
        return "public"
    elif legacy_count > 0:
        return "legacy"
    else:
        return None

