    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Check the signature of the message
    try:
        doc.signature.verify(signature, public_key)
    except (ValueError, xml.etree.ElementTree.ParseError) as e:
        return False

    # Check the signature of the elements
    for element in doc:
        if element.tag == 'Signature':
            continue
        try:
            element.signature
        except xml.etree.ElementTree.ParseError:
            continue
        if element.signature != signature:
            return False

    return True

