    try:
        verified = public_key.verify(signature, element_to_verify.getroottree())
    except Exception as e:
        raise InvalidElementError("Error while verifying element: {}".format(e)) from e

    if not verified:
        raise InvalidElementError("Signature verification failed")


    verified_parsed = etree.fromstring(document)

