def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """

    if not public_key:
        raise ValueError("No public key provided")

    if not doc:
        raise ValueError("No document provided")

    if not signature:
        raise ValueError("No signature provided")

    try:
        r = securesystemslib.keys.verify_signature(
            signature,
            pubkey=public_key,
            data=doc,
            strict=False
        )
    except securesystemslib.exceptions.FormatError:
        return False
    else:
        return r

