def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import xml.etree.ElementTree as ET
    import requests

    url = "https://" + host + "/host-meta.xml"

    try:
        response = requests.get(url)
    except requests.exceptions.RequestException:
        raise ValueError("Unable to connect to the given host: " + host)

    if response.status_code != 200:
        raise ValueError("The server returned a non-200 status code: " + str(response.status_code))

    tree = ET.fromstring(response.content)
    xrd = tree.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link[@rel='lrdd']")
    if xrd is None:
        raise ValueError("The response did not contain the expected LRDD link")
    return XRD.from_xml(xrd)

