    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """

    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)

        return (response.status_code, None)

    except Exception as error:
        return (None, error)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        status_code = response.status_code
    except Exception as e:
        status_code = None
        error = e

    return status_code, error

def dict_insert(dic, val, key, *keys):
  if not keys:
    dic[key] = val
  else:
    if key not in dic:
      dic[key] = {}
    dict_insert(dic[key], val, *keys)

def list_of_file_names(settings_dirs, spec_option):
    """Create a list of all file names in the specified directories, recursively

    Args:
        settings_dirs (List[str]): The directories to search for files
        spec_option (str): The option for which the files should be filtered

    Returns:
        List[str]: A list of all file names that match the specified option
    """
    file_names = []
    for settings_dir in settings_dirs:
        for dir_path, _, files in os.walk(settings_dir):
            for file in files:
                if file.startswith(spec_option):
                    file_path = os.path.join(dir_path, file)
                    file_names.append(file_path)
    return file_names

