def validate_from_content(cls, spec_content=None):
    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file.
    :raise IRValidatorException: When mandatory data is missing in spec file.
    :return: Dictionary with data loaded from a spec (YAML) file.
    """

    if not spec_content:
        raise IRValidatorException("No data found")

    if not isinstance(spec_content, dict):
        raise IRValidatorException("Invalid data format")

    if "info" not in spec_content:
        raise IRValidatorException("Missing \"info\" section")

    if "swagger" not in spec_content["info"]:
        raise IRValidatorException("Invalid \"info\" section")

    if "openapi" not in spec_content["info"]["swagger"]:
        raise IRValidatorException("Invalid \"swagger\" section")

    if spec_content["info"]["swagger"]["openapi"] != "3.0.2":
        raise IRValidatorException("Unsupported OpenAPI version")

    if "paths" not in spec_content:
        raise IRValidatorException("Missing \"paths\" section")

    if not isinstance(spec_content["paths"], dict):
        raise IRValidatorException("Invalid \"paths\" section")

    for path, value in spec_content["paths"].items():
        if not isinstance(value, dict):
            raise IRValidatorException("\"paths\" section is invalid")
        if "get" not in value and "post" not in value:
            raise IRValidatorException("Missing \"get\" or \"post\" operation in path " + path)

    if "components" not in spec_content:
        raise IRValidatorException("Missing \"components\" section")

    if not isinstance(spec_content["components"], dict):
        raise IRValidatorException("Invalid \"components\" section")

    if "schemas" not in spec_content["components"]:
        raise IRValidatorException("Missing \"schemas\" section")

    if not isinstance(spec_content["components"]["schemas"], dict):
        raise IRValidatorException

def validate_from_content(cls, spec_content):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    mandatory_fields = ["intents", "entities", "templates"]

    if spec_content is None:
        raise IRValidatorException("No content provided.")

    if not all(field in spec_content for field in mandatory_fields):
        missing_fields = [
            field for field in mandatory_fields if field not in spec_content
        ]
        raise IRValidatorException(
            "Missing mandatory fields: " + ", ".join(missing_fields)
        )

    intent_schema = spec_content["intents"]
    if not isinstance(intent_schema, dict):
        raise IRValidatorException("Invalid intent schema.")

    entity_schema = spec_content["entities"]
    if not isinstance(entity_schema, dict):
        raise IRValidatorException("Invalid entity schema.")

    template_schema = spec_content["templates"]
    if not isinstance(template_schema, dict):
        raise IRValidatorException("Invalid template schema.")

    for intent in intent_schema:
        if intent.lower() not in INTENTS.keys():
            raise IRValidatorException(f"Invalid intent: {intent}.")

    for entity in entity_schema:
        if entity.lower() not in ENTITIES.keys():
            raise IRValidatorException(f"Invalid entity: {entity}.")

    for template in template_schema:
        if (
            template not in TEMPLATES.keys()
            and template not in INTENT_TEMPLATES.keys()
        ):
            raise IRValidatorException(f"Invalid template: {template}.")

    return spec_content

def validate_from_file(yaml_file):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    # Check if YAML file exists
    if not os.path.exists(yaml_file):
        raise IRValidatorException("YAML file does not exist")

    # Load YAML file
    with open(yaml_file, "r") as f:
        data = yaml.safe_load(f)

    # Validate required fields
    if not data.get("name"):
        raise IRValidatorException("Name is missing in the YAML file")

    if not data.get("type"):
        raise IRValidatorException("Type is missing in the YAML file")

    if not data.get("version"):
        raise IRValidatorException("Version is missing in the YAML file")

    if not data.get("id"):
        raise IRValidatorException("ID is missing in the YAML file")

    # Validate additional fields
    if data.get("labels"):
        if not isinstance(data["labels"], list):
            raise IRValidatorException("Labels must be a list in the YAML file")

    if data.get("description"):
        if not isinstance(data["description"], str):
            raise IRValidatorException("Description must be a string in the YAML file")

    return data

def validate_from_file(yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    import yaml
    from yaml.scanner import ScannerError

    # Load YAML file
    with open(yaml_file, 'r') as f:
        try:
            data = yaml.safe_load(f)
        except ScannerError as e:
            raise IRValidatorException('Error loading YAML file: {}'.format(e))

    # Check for mandatory fields
    required_fields = ['api_name', 'api_version', 'username', 'password', 'url', 'apps']
    for field in required_fields:
        if field not in data:
            raise IRValidatorException('Mandatory field "{}" is missing from YAML file'.format(field))

    # Check if apps field is a list
    if not isinstance(data['apps'], list):
        raise IRValidatorException('"apps" field in YAML file must be a list')

    # Check if every app in apps field has a name and a url
    for app in data['apps']:
        if 'name' not in app or 'url' not in app:
            raise IRValidatorException('Every app in the "apps" list in the YAML file must have a "name" and a "url"')

    # Check if every app in apps field has a valid url
    for app in data['apps']:
        try:
            url = app['url']
            result = urlparse(url)
            if not all([result.scheme, result.netloc, result.path]):
                raise IRValidatorException('URL in "apps" list in the YAML file is not valid')
        except IRValidatorException:
            raise IRValidatorException('URL in "apps" list in the YAML file is not valid')

    return data

def validate_from_file(yaml_file):
    """
