        for sub_field in sub_fields:
            if sub_field not in data[field]:
                raise IRValidatorException(
                    f"Mandatory sub-field '{sub_field}' is missing from '{field}' field in YAML file {yaml_file}"
                )

    # Check if the data has all required sub-fields
    for field, sub_fields in cls.OPTIONAL_SUB_FIELDS.items():
        if field not in data:
            continue
        for sub_field in sub_fields:
            if sub_field not in data[field]:
                logging.warning(
                    "Optional sub-field '%s' not found in '%s' field in YAML file %s",
                    sub_field,
                    field,
                    yaml_file,
                )

    # Validate the data
    for field, validator in cls.FIELD_VALIDATORS.items():
        if field not in data:
            continue

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): The parser dictionary

    Returns:
        dict: The updated parser dictionary
    """

    # Create a copy of the parser dictionary so we don't modify the original
    parser_dict = parser_dict.copy()

    # Loop through each key in the parser dictionary and add the appropriate include groups
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            # If the value is a dictionary, add the include groups to the respective key
            parser_dict[key] = self._add_include_groups_to_spec(value)
        elif isinstance(value, list):
            # If the value is a list, loop through each item in the list and add the include groups to the respective spec
            for item in value:
                if isinstance(item, dict):
                    parser_dict[key].append(self._add_include_groups_to_spec(item))

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Arguments:
        parser_dict (dict): The parser dictionary
    """

    for key, value in parser_dict.items():
        if isinstance(value, str) and value.startswith('include'):
            include_path = value[8:]
            include_dict = self.parser.dict_from_file(include_path)
            if include_dict:
                # combine the included dict with the current dict
                self.dict.update(include_dict)
            else:
                raise ValueError(f"Failed to include dict from '{include_path}'")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict: The dictionary containing the parsed spec file.
    """
    includes = []

    for group in parser_dict["includes"]:
        if isinstance(group, dict):
            includes.append(group.copy())
        else:
            includes.append(group)

    for include in includes:
        if "file" in include:
            file_name = include["file"]
            if not os.path.isfile(file_name):
                raise FileNotFoundError("Could not find include file '{}'".format(file_name))

            with open(file_name, "r") as f:
                spec = f.read()
                parser = GraphSpecParser()
                parse_dict = parser.parse(spec)

            for key, value in parse_dict.items():
                if key not in self.spec:
                    self.spec[key] = value
                else:
                    self.spec[key] = list(set(self.spec[key] + value))
        else:
            raise ValueError("Invalid 'include' directive in spec file")

        self.spec.pop("includes", None)

    return self.spec

def get_spec_defaults(self):
    "Resolve arguments' values from spec and other sources."

    def try_int(value):
        """Try to parse an integer."""
        try:
            return int(value)
        except ValueError:
            return value

    args = self.args
    if args:
        if isinstance(args, list):
            for i, arg in enumerate(args):
                if not isinstance(arg, list) and arg.startswith("$"):
                    args[i] = try_int(args[i])
        else:
            for name, value in args.items():
                if value is not None and value.startswith("$"):
                    args[name] = try_int(value)

    kwargs = self.kwargs
    if kwargs:
        for name, value in kwargs.items():
            if value is not None and value.startswith("$"):
                kwargs[name] = try_int(value)

