    """
    # This function is a mechanism to deprecate old arguments and their usage, and issue a warning message to the user.
    # The idea is to mark arguments that are deprecated in the arguments schema, and then detect their presence in the input
    # arguments and issue a warning message with the updated alternatives.

    # Handle deprecated `[-m|--max-employee]` argument in the cli.
    if "--max-employee" in cli_args:
        print(
            "WARNING: Argument `[-m|--max-employee]` is deprecated, please use `[--max-number-of-employees]` instead."
        )

    # Handle deprecated `[-e|--employee-type]` argument in the cli.
    if "--employee-type" in cli_args:
        print(
            "WARNING: Argument `[-e|--employee-type]` is deprecated, please use `[--employer-type]` instead."
        )

    # Handle deprecated `answer_file_args` arguments.
    # This can be done by checking the keys of the dictionary, and then compare them to the deprecated arguments.
    for arg in ["max_employee", "employee_type"]:
        if arg in answer_file_args:
            print(
                f"WARNING: \"{arg}\" argument in answer file is deprecated, please remove it and use the updated version."
            )

