def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # Set default values for optional parameters
    if verbose is None:
        verbose = 0
    if extra_vars is None:
        extra_vars = {}
    if ansible_args is None:
        ansible_args = {}

    # Prepare the command-line arguments for ansible-playbook
    args = ['ansible-playbook', playbook_path]
    if verbose is not None:
        args.append('-' + ('v' * verbose))
    if extra_vars:
        args.extend(['-e', json.dumps(extra_vars)])
    for arg_name, arg_value in ansible_args.items():
        args.extend(['--' + arg_name, arg_value])

    # Execute the ansible-playbook command
    process = subprocess.Popen(args, shell=True, cwd=ir_workspace.working_directory)

    # Wait for the command to finish and handle any output
    returncode = process.wait()
    if returncode == 0:
        if args and args[0] == 'playbook':
            print(f"Playbook '{args[1]}' executed successfully")
        else:
            print("Executed Ansible playbook successfully")
    else:
        print(f"Ansible playbook execution failed with return code {returncode}")
        raise CommandFailedError(returncode)

