        arg_parser = self.parser_args[parser_name]
        if name in arg_parser:
            arg = arg_parser[name]
            if arg.type == int:
                values_dict[name] = int(value)
            elif arg.type == bool:
                if value.lower() == "true":
                    values_dict[name] = True
                elif value.lower() == "false":
                    values_dict[name] = False
